entries[18239] = { ["name"] = "Muster: Schattenhauthandschuhe", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Schattenhauthandschuhen.\nBenötigt Klassische Lederverarbeitung (200)\nVerkaufspreis:\nSchattenhauthandschuhe\nWird beim Anlegen gebunden\nHände Leder\n3 Rüstung\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nHaltbarkeit 50 / 50\nVerkaufspreis:\nBenötigt Dickes Leder (6), Schattenseide (8), Geschmeidiger schwerer Balg (4), Schwerer Seidenfaden\nOptionale Reagenzien: [] (#49)" }
