entries[18650] = { ["name"] = "Bauplan: EZ-Thro-Dynamit II", ["text"] = "Benutzen: Lehrt Euch die Herstellung von EZ-Thro-Dynamit II.\nBenötigt Klassische Ingenieurskunst (200)\nVerkaufspreis:\nDynamit mit Zielhilfe II\nBenutzen: Fügt 8 Feuerschaden in einem Radius von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"\nVerkaufspreis:\nBenötigt Robustes Sprengpulver , Magiestoff (2)" }
