entries[18652] = { ["name"] = "Bauplan: Gyrofrosteisreflektor", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Gyrofrosteisreflektors.\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nGyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+3 Frostwiderstand\nBenutzen: Reflektiert 5 Sek. lang Frostzauber auf den Zaubernden. Es besteht die Chance, dass dem Effekt widerstanden wird, wenn der Zaubernde über Stufe 49 ist. (5 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nBenötigt Thoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)\nOptionale Reagenzien: [] (#50)" }
entries[18653] = { ["name"] = "Bauplan: Goblinüberbrückungskabel XL", ["text"] = "Benutzen: Lehrt Euch die Herstellung von Goblinüberbrückungskabeln XL.\nBenötigt Klassische Ingenieurskunst (265)\nBenötigt Gobliningenieur\nVerkaufspreis:\nGoblinüberbrückungskabel XL\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Verbündeten ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (265)\nVerkaufspreis:\nBenötigt Thoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)" }
