entries[19019] = { ["name"] = "Donnerzorn, Gesegnete Klinge des Windsuchers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Schwert\n3 - 7 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\n+1 Beweglichkeit\n+1 Ausdauer\n+1 Feuerwiderstand\n+1 Naturwiderstand\nHaltbarkeit 130 / 130\nTrefferchance: Deckt Euren Gegner mit Blitzschlägen ein, die 4 Naturschaden verursachen und zu in der Nähe befindlichen Feinden weiterspringen. Jeder Sprung verringert den Naturwiderstand des Ziels um 0 . Wirkt auf insgesamt 5 Ziele. Euer Primärziel wird außerdem von einem Wirbelsturm umgeben, welcher dessen Angriffstempo 12 Sek. lang um 20% verringert.\nVerkaufspreis:" }
