entries[19215] = { ["name"] = "Muster: Weisheit der Holzschlundfeste", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Weisheit der Holzschlundfeste näht.\nBenötigt Klassische Schneiderei (290)\nBenötigt Holzschlundfeste\n- Wohlwollend\nVerkaufspreis:\nWeisheit der Holzschlundfeste\nWird beim Anlegen gebunden\nTaille Stoff\n2 Rüstung\n+4 Intelligenz\n+ 3 Vielseitigkeit\nHaltbarkeit 50 / 50\nVerkaufspreis:\nBenötigt Runenstoffballen (8), Essenz der Erde (3), Essenz des Lebens (3), Eisenweberseide (2)" }
entries[19216] = { ["name"] = "Muster: Argentumstiefel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Argentumstiefeln.\nBenötigt Klassische Schneiderei (290)\nBenötigt Argentumdämmerung\n- Wohlwollend\nVerkaufspreis:\nArgentumstiefel\nWird beim Anlegen gebunden\nFüße Stoff\n2 Rüstung\n+4 Ausdauer\n+ 2 Vielseitigkeit\n+0 Schattenwiderstand\nHaltbarkeit 65 / 65\nVerkaufspreis:\nBenötigt Runenstoffballen (6), Verzaubertes Leder (4), Goldene Perle (2), Wächterstein (2), Eisenweberseide (2)" }
